      "steps": [
        "El usuario `pending` intenta enviar un mensaje de texto",
        "El usuario `pending` intenta enviar un mensaje de archivo",
        "El usuario `pending` intenta enviar un mensaje de imagen",
        "El usuario `pending` intenta enviar un mensaje de video",
